-- scripts/add_enoch_watchers.sql
-- Mainstream-traditions pass: the missing chiefs of tens among the fallen
-- Watchers of 1 Enoch (Book of Watchers, 6:7 / 8:3), Second Temple Jewish/Christian
-- angelology. Verbatim, substring-gated against R. H. Charles's translation
-- (Wikisource). 10 cite the 6:7 leaders-list; Araqiel/Ezeqeel/Armaros cite their
-- 8:3 teaching. Variant spellings (Asael, Baraqijal, Samsapeel, Semjaza, Samiazaz,
-- Arakiba) added as aliases to existing entities, not duplicated. No AI prose.

BEGIN;

ON CONFLICT (entity_id) DO NOTHING;

SELECT 'ENT_ISR_AZAZEL','Asael','variant','en','SRC_1_ENOCH','high','candidate_verified_name','Variant spelling of this Watcher in 1 Enoch (Charles).' WHERE NOT EXISTS (SELECT 1 FROM entity_aliases WHERE entity_id='ENT_ISR_AZAZEL' AND alias_name='Asael')
UNION ALL
SELECT 'ENT_ISR_BARAQIEL','Baraqijal','variant','en','SRC_1_ENOCH','high','candidate_verified_name','Variant spelling of this Watcher in 1 Enoch (Charles).' WHERE NOT EXISTS (SELECT 1 FROM entity_aliases WHERE entity_id='ENT_ISR_BARAQIEL' AND alias_name='Baraqijal')
UNION ALL
SELECT 'ENT_JM_SHAMSHIEL','Samsapeel','variant','en','SRC_1_ENOCH','high','candidate_verified_name','Variant spelling of this Watcher in 1 Enoch (Charles).' WHERE NOT EXISTS (SELECT 1 FROM entity_aliases WHERE entity_id='ENT_JM_SHAMSHIEL' AND alias_name='Samsapeel')
UNION ALL
SELECT 'ENT_ISR_SHEMIHAZAH','Semjaza','variant','en','SRC_1_ENOCH','high','candidate_verified_name','Variant spelling of this Watcher in 1 Enoch (Charles).' WHERE NOT EXISTS (SELECT 1 FROM entity_aliases WHERE entity_id='ENT_ISR_SHEMIHAZAH' AND alias_name='Semjaza')
UNION ALL
SELECT 'ENT_ISR_SHEMIHAZAH','Samiazaz','variant','en','SRC_1_ENOCH','high','candidate_verified_name','Variant spelling of this Watcher in 1 Enoch (Charles).' WHERE NOT EXISTS (SELECT 1 FROM entity_aliases WHERE entity_id='ENT_ISR_SHEMIHAZAH' AND alias_name='Samiazaz')
UNION ALL
SELECT 'ENT_ISR_ARAQIEL','Arakiba','variant','en','SRC_1_ENOCH','high','candidate_verified_name','Variant spelling of this Watcher in 1 Enoch (Charles).' WHERE NOT EXISTS (SELECT 1 FROM entity_aliases WHERE entity_id='ENT_ISR_ARAQIEL' AND alias_name='Arakiba');

ON CONFLICT (citation_id) DO UPDATE SET quote=EXCLUDED.quote, locus=EXCLUDED.locus, source_url=EXCLUDED.source_url;

COMMIT;
